            id={`tabs-segmented-panel-${id}`}
            aria-labelledby={`tabs-segmented-tab-${id}`}
            hidden={custom !== id}
          >
            <Typography variant="body2">{label}</Typography>
          </TabPanel>
        ))}
      </div>
    </>
  );
}

