      />
      {drinks.map((drink) => (
        <FormControlLabel
          key={drink}
          label={drink}
          control={
            <Checkbox
              id={drink.toLowerCase()}
              checked={selected.includes(drink)}
              onChange={(next) =>
                setSelected(next ? [...selected, drink] : selected.filter((d) => d !== drink))
